{
    // Arrange
    var delayProvider = new DelayProvider();
    var stopwatch = new System.Diagnostics.Stopwatch();

    // Act
    stopwatch.Start();
    await delayProvider.DelayAsync(1);
    stopwatch.Stop();

    // Assert
    Assert.True(stopwatch.ElapsedMilliseconds < 10, 
        $"The delay should complete in less than 10ms, but it took {stopwatch.ElapsedMilliseconds}ms");

[Fact]
public async Task DelayAsync_CancelledBeforeCompletion_ThrowsTaskCanceledException()
{
    // Arrange
    var delayProvider = new DelayProvider();
    var cts = new CancellationTokenSource();
    var delay = 1000; // 1 second delay

    // Act
    var delayTask = delayProvider.DelayAsync(delay, cts.Token);
    cts.Cancel(); // Cancel immediately

    // Assert
    await Assert.ThrowsAsync<TaskCanceledException>(() => delayTask);

