[Fact]
public async Task DelayAsync_WithMaxIntValue_ShouldNotThrowException()
{
    // Arrange
    var delayProvider = new DelayProvider();
    var cts = new CancellationTokenSource(TimeSpan.FromMilliseconds(100)); // Short timeout for test purposes

    // Act & Assert
