[Fact]
public async Task DelayAsync_WithNonTriggeredCancellationToken_CompletesSuccessfully()
{
    // Arrange
    var delayProvider = new DelayProvider();
    var cts = new CancellationTokenSource();
    var milliseconds = 100;

    // Act
    var delayTask = delayProvider.DelayAsync(milliseconds, cts.Token);
    
    // Assert
    await Assert.ThrowsAsync<TimeoutException>(() => delayTask.WaitAsync(TimeSpan.FromMilliseconds(50)));
    
    await Task.Delay(milliseconds + 50); // Wait a bit longer than the delay
    
    Assert.True(delayTask.IsCompleted, "The delay task should complete after the specified time.");
    Assert.False(delayTask.IsCanceled, "The delay task should not be canceled.");
